challenge-set.solution:
class FieldError(Exception):
    def __init__(self, field):
        super().__init__(f"missing {field}")
        self.field = field


def check(record):
    for field in ("name", "level"):
        if field not in record:
            raise FieldError(field)
    return "ok"


def report(records):
    out = []
    for record in records:
        try:
            out.append(check(record))
        except FieldError as e:
            out.append(e.field)
    return out

class Transaction:
    def __init__(self):
        self.applied = []

    def __enter__(self):
        return self

    def apply(self, item):
        self.applied.append(item)

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is not None:
            self.applied = []
        return False


def run_transaction(items, fail_on):
    tx = Transaction()
    try:
        with tx as t:
            for item in items:
                t.apply(item)
                if item == fail_on:
                    raise ValueError(item)
    except ValueError:
        pass
    return tx.applied

