class SpellError(Exception):
    pass


class ManaError(SpellError):
    pass


class TargetError(SpellError):
    pass


def classify(kind):
    if kind == "mana":
        raise ManaError(kind)
    if kind == "target":
        raise TargetError(kind)
    if kind == "other":
        raise SpellError(kind)
    return "fine"


def describe(kind):
    try:
        return classify(kind)
    except ManaError:
        return "mana problem"
    except TargetError:
        return "target problem"
    except SpellError:
        return "spell problem"

