exam.solution:
class AuditError(Exception):
    pass


class Rejected(AuditError):
    pass


class Audit:
    def __init__(self):
        self.entries = []

    def __enter__(self):
        return self

    def record(self, entry):
        if entry == "":
            raise Rejected(entry)
        self.entries.append(entry)

    def __exit__(self, exc_type, exc_value, traceback):
        self.entries.append("closed")
        return False


def audit(entries):
    log = Audit()
    try:
        with log as a:
            for entry in entries:
                a.record(entry)
    except AuditError:
        pass
    return log.entries
